{
  "title": "修复通讯",
  "scene": "飞船迫降在一个未知星球，周围是荒凉的岩石。你发现一台损毁的通讯器，上面有几个闪烁的灯光。你注意到旁边的控制面板上有几个按钮，似乎与通讯器相连。",
  "goal": "尝试修复通讯器，希望联系救援队伍。",
  "clue": "闪烁的灯光和旁边的控制面板。",
  "choices": [
    {"id": "A", "text": "按控制面板上的红色按钮", "outcome": "红色按钮被按了一下，但没有明显变化，通讯器依然没有反应。", "result": "partial", "next": "retry"},
    {"id": "B", "text": "检查通讯器的线路是否正常", "outcome": "检查后发现线路确实有断裂，于是你迅速接上断裂的电缆，通讯器发出嗡嗡声后恢复了。", "result": "success", "next": "next_level"},
    {"id": "C", "text": "尝试扭动通讯器的旋钮", "outcome": "旋钮扭动了几下，但是没有任何反应，通讯器仍然处在无响应状态。", "result": "fail", "next": "retry"}
  ]
}
